#'
#' @export
descDistances <- function(
    data,
    varDst = NULL,
    dstCoR = "columns",
    dstStd = "none",
    dstCtg = "ctgCnt",
    dstCnt = "euclid",
    pwrCnt = 2,
    rt_Cnt = 2,
    dstFrq = "chisq",
    dstBnM = "jaccards",
    p__BnM = "1",
    np_BnM = "0",
    dstBnC = "k2",
    p__BnC = "1",
    np_BnC = "0",
    dstBnP = "q",
    p__BnP = "1",
    np_BnP = "0",
    dstBnO = "bseuclid",
    p__BnO = "1",
    np_BnO = "0",
    shwHlp = FALSE,
    jxfLog = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("descDistances requires jmvcore to be installed (restart may be required)")

    if ( ! missing(varDst)) varDst <- jmvcore::resolveQuo(jmvcore::enquo(varDst))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(varDst), varDst, NULL))


    options <- descDistancesOptions$new(
        varDst = varDst,
        dstCoR = dstCoR,
        dstStd = dstStd,
        dstCtg = dstCtg,
        dstCnt = dstCnt,
        pwrCnt = pwrCnt,
        rt_Cnt = rt_Cnt,
        dstFrq = dstFrq,
        dstBnM = dstBnM,
        p__BnM = p__BnM,
        np_BnM = np_BnM,
        dstBnC = dstBnC,
        p__BnC = p__BnC,
        np_BnC = np_BnC,
        dstBnP = dstBnP,
        p__BnP = p__BnP,
        np_BnP = np_BnP,
        dstBnO = dstBnO,
        p__BnO = p__BnO,
        np_BnO = np_BnO,
        shwHlp = shwHlp,
        jxfLog = jxfLog)

    analysis <- descDistancesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

